const la=""+new URL("kapak-tam-oVOaamOm.webp",import.meta.url).href,ma=""+new URL("s01-tam-2U0RU3U-.webp",import.meta.url).href,oa=""+new URL("s02-tam-DxOIwS1F.webp",import.meta.url).href,da=""+new URL("s03-tam-xRkhsD5F.webp",import.meta.url).href,sa=""+new URL("s04-tam-CnHSqOeX.webp",import.meta.url).href,ya=""+new URL("s05-tam-zLPRPMHL.webp",import.meta.url).href,ba=""+new URL("s06-tam-DvUePwJs.webp",import.meta.url).href,za=""+new URL("s07-tam-C-pRIYuH.webp",import.meta.url).href,pa=""+new URL("s08-tam-KVhPwhcR.webp",import.meta.url).href,ca=""+new URL("s09-tam-DBbVHchs.webp",import.meta.url).href,Ka=""+new URL("s10-tam-jnzQGTPT.webp",import.meta.url).href,ga=""+new URL("s11-tam-BYAchc2T.webp",import.meta.url).href,Ba=""+new URL("s12-tam-RXPwUscU.webp",import.meta.url).href,va=""+new URL("s13-tam-B1MduAFN.webp",import.meta.url).href,fa=""+new URL("s14-tam-fLD6TMIS.webp",import.meta.url).href,ha=""+new URL("yuz-anne-NZrJ9te-.webp",import.meta.url).href,Da=""+new URL("yuz-baba-BHaZ-nTr.webp",import.meta.url).href,Aa=""+new URL("yuz-bulut-iLwFKsPr.webp",import.meta.url).href,_a=""+new URL("yuz-kino-CDmGA6iA.webp",import.meta.url).href,La=""+new URL("yuz-lokum-B-iC0TB7.webp",import.meta.url).href,Ma=""+new URL("yuz-mino-BdQQghrT.webp",import.meta.url).href,Sa=""+new URL("yuz-ogretmen-BeyrY-qO.webp",import.meta.url).href,Ta=""+new URL("yuz-tombi-DirUjXRh.webp",import.meta.url).href,wa=""+new URL("kapak-DFWUsji0.webp",import.meta.url).href,Ea=""+new URL("kapak-BO99Y2If.webp",import.meta.url).href,Fa=""+new URL("kapak-KlX8H5YU.webp",import.meta.url).href,Ua=""+new URL("kapak-DaPAK56N.webp",import.meta.url).href,Ca=""+new URL("kapak-CoUfjivD.webp",import.meta.url).href,$a=""+new URL("kapak-D8Ye0TyG.webp",import.meta.url).href,Ra=""+new URL("kapak-ONGvNVnw.webp",import.meta.url).href,p="Kitap 1: Kino Okula Başlıyor. Metin ekip/senaryo/KITAP-MINO-KINO.md §2.5'ten birebir (değiştirilmez). kim: konuşan (anlatici, kino, anne, baba, lokum, mino, ogretmen, bulut, tombi, cocuklar, ses). not: yalnız seslendirme / resim için yönerge, sayfada basılmaz. tarif: resim gelene kadar yer tutucuda görünen kısa tarif. Seslendirme: content/kitap-ses.json (her satır konuşanın kendi ElevenLabs sesiyle, scripts/kitap-seslendir.ts); kayıt yoksa sessiz, cihaz sesi yok.",c="okul",K="Kino Okula Başlıyor",g={renk:"#F6C98A",tarif:"Çınar Anaokulu'nun kapısında sırt çantalı Kino el sallıyor.",satirlar:[{kim:"anlatici",metin:"Bugün Kino'nun başından neler geçti, bir bakalım."}]},B=[{no:1,ad:"Ters önlük",renk:"#CFE3F2",tarif:"Sabah, çocuk odası. Kino önlüğünü ters giymiş; Lokum karyolasında uykulu.",satirlar:[{kim:"anlatici",metin:"Pazartesi sabahıydı. Bugün Kino'nun okuldaki ilk günüydü."},{kim:"anlatici",metin:"Kino herkesten önce kalktı. Önlüğünü de kendisi giydi. Biraz ters ama."},{kim:"kino",metin:"[excited] Ben büyüdüm artık! Okula gidiyorum!"}]},{no:2,ad:"Kahvaltı",renk:"#F7DDB0",tarif:"Kahvaltı masası. Baba elinde simitle uyuyor; Lokum Kino'nun çantasını sırtına geçirmiş.",satirlar:[{kim:"anlatici",metin:"Mutfakta Baba yine uyuyakalmıştı. Hem de elinde simitle."},{kim:"anne",metin:"Çay?"},{kim:"baba",metin:"[surprised] Çay mı? Kalktım!"},{kim:"anlatici",metin:"Lokum da okula gitmek istedi. Ama Kino'nun çantası Lokum'dan büyüktü."},{kim:"lokum",metin:"[giggles] Ben de okul!"},{kim:"kino",metin:"Sen daha küçüksün, Lokum."}]},{no:3,ad:"Kapıda Mino",renk:"#D7ECC6",tarif:"Apartmanın önü. Anne Kino'nun elini tutuyor; Mino hoplayarak önde.",satirlar:[{kim:"anlatici",metin:"Kapıda Mino bekliyordu. Mino aynı okula geçen ay başlamıştı."},{kim:"mino",metin:"[excited] Okulda kocaman bloklar var! Bir de kum havuzu!"},{kim:"mino",metin:"Ben ilk gün biraz korkmuştum ama."},{kim:"kino",metin:"[happy] Ben hiç korkmam!"},{kim:"anlatici",metin:"Kino çok emindi. Kuyruğu bile emindi."}]},{no:4,ad:"Kocaman okul",renk:"#F9D3C4",tarif:"Okulun girişi. Kino Anne'nin arkasına saklanmış; yalnız bir kulağı görünüyor.",satirlar:[{kim:"anlatici",metin:"Okul kocamandı. Ve çok gürültülüydü."},{kim:"anlatici",metin:"Kino'nun kuyruğu yavaş yavaş aşağı indi."},{kim:"ogretmen",metin:"[happy] Hoş geldin, Kino!"},{kim:"anlatici",metin:"Kino, Anne'nin arkasına saklandı. Yalnız bir kulağı dışarıda kaldı."},{kim:"ogretmen",metin:"[curious] Aa, bu uzun kulak kimin acaba?"}]},{no:5,ad:"El",renk:"#F3E3C3",tarif:"Anne diz çökmüş, Kino'nun elini iki eli arasında tutuyor.",satirlar:[{kim:"anlatici",metin:"Kino büyümüştü. Ama eli, Anne'nin elini bırakmak istemedi."},{kim:"anne",metin:"Ben şimdi gideceğim. Ama geri geleceğim. Bak."},{kim:"anne",not:"Kino'nun parmaklarını tek tek açarak",metin:"Önce oyun... sonra yemek... sonra Annen gelecek."},{kim:"kino",metin:"[whispers] Söz mü?"},{kim:"anne",metin:"Söz."},{kim:"anlatici",metin:"Anne de biraz üzüldü. Ama gülümsedi."}]},{no:6,ad:"Askı",renk:"#DCD6F2",tarif:"Askıların önünde Kino tek başına. Çantası askıda.",satirlar:[{kim:"anlatici",metin:"Anne gitti. Mino kum havuzuna koştu."},{kim:"mino",metin:"[excited] Hadi Kino! Gelince gel!"},{kim:"anlatici",metin:"Kino askıların önünde tek başına kaldı."},{kim:"ogretmen",metin:"Bu senin askın, Kino. Üstünde senin resmin var."},{kim:"ogretmen",metin:"Hazır olunca gel, olur mu?"},{kim:"anlatici",metin:"Kino çantasını astı. Pat! Çantadan bir şey düştü."}]},{no:7,ad:"Kuzu",renk:"#F2E6D0",tarif:"Kino yerde, Kuzu'yu karşısında tutuyor; burun buruna.",satirlar:[{kim:"anlatici",metin:"Düşen şey, Lokum'un Kuzu'suydu!"},{kim:"kino",metin:"[surprised] Kuzu? Sen de mi okula geldin?"},{kim:"anlatici",metin:"Kuzu'nun kulakları da düşüktü. Tıpkı Kino'nunkiler gibi."},{kim:"kino",metin:"[whispers] Korkma, Kuzu. Bak."},{kim:"kino",not:"Kuzu'nun ayaklarını tek tek tutarak",metin:"[whispers] Önce oyun, sonra yemek, sonra Annem gelecek."},{kim:"anlatici",metin:"Kuzu biraz rahatladı. Kino da."}]},{no:8,ad:"Blok köşesi",renk:"#CDE8E4",tarif:"Blok köşesi. Bulut elinde mavi blokla oturuyor; Kino ona doğru geliyor.",satirlar:[{kim:"anlatici",metin:"Önce oyun. Kino etrafına baktı."},{kim:"anlatici",metin:"Blok köşesinde biri oturuyordu. Elinde tek bir blok, kulakları düşük."},{kim:"bulut",metin:"[curious] O da... kuzu mu?"},{kim:"kino",metin:"Evet! Adı Kuzu. Sen de kuzusun!"},{kim:"bulut",metin:"[giggles] Ben Bulut. Bugün geldim."},{kim:"kino",metin:"Ben de! Kule yapalım mı? Ben kule ustasıyım!"}]},{no:9,ad:"Kule",renk:"#FBE3A6",tarif:"Kino'dan uzun bir blok kulesi. Kino ve Bulut gururla bakıyor.",satirlar:[{kim:"anlatici",metin:"Kule büyüdü, büyüdü, büyüdü."},{kim:"anlatici",metin:"Sonunda Kino'dan bile uzun oldu."},{kim:"kino",metin:"[excited] Ben büyüdüm artık! Kulem de büyüdü!"},{kim:"anlatici",metin:"Tam o sırada kule sallandı. Bir sağa. Bir sola."},{kim:"ses",metin:"GÜM!"},{kim:"anlatici",metin:"Bütün sınıf dönüp baktı."}]},{no:10,ad:"Bir daha!",renk:"#E4D8F5",tarif:"Çocuklar halka olmuş; Kino ortada blok dağıtıyor.",satirlar:[{kim:"anlatici",metin:"Kino bir an kıpırdamadı."},{kim:"bulut",metin:"[laughs] GÜM!"},{kim:"anlatici",metin:"Önce Bulut güldü. Sonra Kino. Sonra bütün sınıf."},{kim:"mino",not:"koşarak gelir",metin:"[excited] O kule senin miydi? Bir daha yapalım!"},{kim:"cocuklar",metin:"Bir daha! Bir daha!"},{kim:"anlatici",metin:"Kino artık yalnız değildi. Kule ustasıydı."}]},{no:11,ad:"Sonra yemek",renk:"#FADCC0",tarif:"Küçük masalar. Kino'nun beslenme kutusu pişi dolu; Tombi yan masadan bakıyor.",satirlar:[{kim:"anlatici",metin:"Sonra yemek. Kino beslenme kutusunu açtı."},{kim:"anlatici",metin:"İçinde Babaanne'nin pişileri vardı. Hem de bir sürü."},{kim:"kino",not:"iki parmağını kaldırarak",metin:"[excited] Önce oyun... bitti! Sonra yemek... şimdi!"},{kim:"kino",metin:"Bulut, pişi ister misin? Mino, sen?"},{kim:"tombi",not:"yan masadan",metin:"[sighs] Ben acıktım..."},{kim:"anlatici",metin:"Babaanne arkadaşlar için de koymuştu. Babaanne her şeyi bilirdi."}]},{no:12,ad:"Kule bitmedi!",renk:"#D3E7F5",tarif:"Kapıda Anne kollarını açmış. Kino arkası dönük, kuleye son bloğu koyuyor.",satirlar:[{kim:"anlatici",metin:"Önce oyun oldu. Sonra yemek. Sonra kapı açıldı."},{kim:"anne",metin:"Kino! Eve gidiyoruz!"},{kim:"kino",metin:"[gasps] Ama Anne! Daha kule bitmedi!"},{kim:"anlatici",metin:"Sabah Anne'nin elini bırakmayan Kino, şimdi kuleyi bırakmıyordu."}]},{no:13,ad:"Abi",renk:"#F5D9E4",tarif:"Evin girişi. Kino diz çökmüş, Lokum'un parmaklarını açıyor.",satirlar:[{kim:"anlatici",metin:"Evde Lokum kapıda bekliyordu."},{kim:"lokum",metin:"Abi! Kuzu?"},{kim:"kino",metin:"Kuzu okula bayıldı. Önce biraz korktu ama."},{kim:"lokum",metin:"[sad] Ben de okul!"},{kim:"kino",not:"Lokum'un parmaklarını tek tek açarak",metin:"Önce oyun, sonra yemek, sonra Annen gelecek."},{kim:"lokum",metin:"[giggles] Sonya Annem gelecek!"}]},{no:14,ad:"Çay bile",renk:"#F8E1A0",tarif:"Akşam sofrası, sarı lamba. Kino elinde kaşıkla uyuyakalmış.",satirlar:[{kim:"anlatici",metin:"Akşam yemeğinde Baba sordu:"},{kim:"baba",metin:"Eee, Kino? Okul nasıldı?"},{kim:"anlatici",metin:"Ama Kino uyuyakalmıştı. Hem de elinde kaşıkla."},{kim:"anne",metin:"[whispers] Çay?"},{kim:"anlatici",metin:"Kino'yu çay bile uyandıramadı."},{kim:"kino",metin:"[sleepy] Önce oyun..."},{kim:"anlatici",metin:"Yarın da güzel bir gün olacaktı."}]}],v={baslik:"Çocuğunuzla konuşmak için:",sorular:["Senin ilk günün nasıldı? (Henüz başlamadıysa: ilk günün nasıl olsun istersin?)","Kino korkunca Kuzu'ya ne söyledi? Sen de bir şeyden korkunca kendine ne söyleyebilirsin?","Kuzu gibi seninle okula gelecek bir şey olsaydı, o ne olurdu?"],not:'Küçük not: "Önce oyun, sonra yemek, sonra Annem gelecek" sözünü çocuğunuzun kendi gününe göre değiştirebilirsiniz (ör. "Önce resim, sonra uyku, sonra Babam gelecek").'},f={aciklama:p,id:c,baslik:K,kapak:g,sayfalar:B,ebeveyn:v},h="doktor",D="Kino Doktora Gidiyor",A={renk:"#F5DBAF",tarif:"Kino, boynunda oyuncak doktor kulaklığıyla yatağının üzerinde.",satirlar:[{kim:"anlatici",metin:"Kino doktora gidiyor."}]},_=[{no:1,ad:"Boy çizgisi",renk:"#F6DAB2",tarif:"Kino kapının yanındaki boy çizgisine yetişmek için parmak uçlarına kalkmış. Annesi gülümseyerek ona bakıyor.",satirlar:[{kim:"anlatici",metin:"O sabah Kino’nun doktor kontrolü vardı. Evden çıkarken kapının yanındaki boy çizgisini gördü. Topuklarını kaldırdı."},{kim:"kino",metin:"Anne, bak! Çizgiyi geçtim!"},{kim:"anlatici",metin:"Annesi eğilip kırmızı ayakkabılarına baktı."},{kim:"anne",metin:"Sen mi uzadın, yoksa ayakkabıların mı?"},{kim:"anlatici",metin:"Kino gülüp topuklarını yere bastı. Çizgi şimdi tam neresine geliyordu? Bunu doktora soracaktı. Annesinin elini tuttu, yola çıktılar."}]},{no:2,ad:"Beyaz kapı",renk:"#F6DAB2",tarif:"Kino muayene odasının kapısında annesinin eteğinin arkasından bakıyor.",satirlar:[{kim:"anlatici",metin:"Beyaz kapı açılınca Kino bir adım attı. Sonra bir adım geri geldi. Muayene masası ona pek yüksek görünmüştü."},{kim:"kino",metin:"[whispers] Anne… Boyum evde de uzuyor. Burada ölçmek şart mı?"},{kim:"anlatici",metin:"Doktor Teyze kapıyı açık tuttu. Kino, annesinin eteğinin arkasından içeri baktı."}]},{no:3,ad:"Mino’nun yıldızı",renk:"#F6DAB2",tarif:"Mino bekleme yerinde kolundaki yıldızı Kino’ya gösteriyor.",satirlar:[{kim:"anlatici",metin:"Kapının yanında turuncu bir kuyruk kıpırdadı. Mino, kontrolünü bitirmişti. Kolunu çevirince küçük bir yıldız göründü."},{kim:"mino",metin:"Ben de kapıda bekledim, biliyor musun? Sonra doktora ne yapacağını sordum. Bana gösterdi."},{kim:"kino",metin:"Önce gösteriyor mu gerçekten?"},{kim:"anlatici",metin:"Mino başını salladı. Kino’nun aklına bir soru daha geldi."}]},{no:4,ad:"Annenin üç adımı",renk:"#F6DAB2",tarif:"Anne, Kino’ya kalp, açık ağız ve yıldız resmi olan bir kart gösteriyor.",satirlar:[{kim:"kino",metin:"Peki kalbimi dinledikten sonra ne olacak?"},{kim:"anlatici",metin:"Annesi yanına çömeldi. Küçük bir kartı Kino’ya çevirdi. Üstünde bir kalp, açık bir ağız ve sarı bir yıldız vardı."},{kim:"anne",metin:"Önce kalbini dinleyecek. Sonra ağzına ve karnına bakacak. En son da yıldızını seçeceksin. Ben yanındayım."},{kim:"kino",metin:"Söz mü?"},{kim:"anne",metin:"Söz."}]},{no:5,ad:"Cepte kim var?",renk:"#F6DAB2",tarif:"Kino montunun cebinden çıkan oyuncak Kuzu’yu kucağına alıyor.",satirlar:[{kim:"anlatici",metin:"Kino masanın kenarına oturdu. Montunu katlarken cebinden beyaz bir kulak sarktı. Bir çekti… Lokum’un Kuzu’su! Kırmızı kurdelesi bile üstündeydi."},{kim:"kino",metin:"Sen de mi kontrole geldin? Gel, kucağıma otur. Buradan daha iyi görürsün."},{kim:"anlatici",metin:"Kino ona yer açarken masanın ne kadar yüksek olduğunu unuttu."}]},{no:6,ad:"Bulut’un boyu",renk:"#F6DAB2",tarif:"Bulut boy ölçerin önünde duruyor. Kino ve Kuzu ölçümün nasıl yapıldığını izliyor.",satirlar:[{kim:"anlatici",metin:"Duvarın dibinde arkadaşı Bulut duruyordu. Topuklarını yere bastı. Doktor Teyze ölçerin küçük tahtasını yavaşça indirip başının üstünde durdurdu."},{kim:"bulut",metin:"Kino, yünüm de boyuma sayılıyor mu acaba?"},{kim:"anlatici",metin:"Kino, Kuzu’nun kabarık başını avucuyla düzeltti."},{kim:"kino",metin:"O zaman bizim Kuzu azıcık kısaldı!"}]},{no:7,ad:"Önce Kuzu",renk:"#F6DAB2",tarif:"Doktor Teyze stetoskobunun ucunu önce oyuncak Kuzu’nun göğsüne değdiriyor.",satirlar:[{kim:"anlatici",metin:"Doktor Teyze kulaklığını taktı. Ucundaki yuvarlak parçayı Kino’ya gösterdi. Kino, parmağının ucuyla dokundu. Biraz serindi."},{kim:"kino",metin:"Önce Kuzu’yu dinleyebilir misiniz?"},{kim:"anlatici",metin:"Doktor Teyze yuvarlak ucu Kuzu’nun göğsüne koydu. Kino da onunla birlikte sessizce bekledi."},{kim:"kino",metin:"Kuzu hazır. Şimdi sıra bende."}]},{no:8,ad:"İçerideki davul",renk:"#F6DAB2",tarif:"Kino stetoskopla kendi kalp atışını duyuyor.",satirlar:[{kim:"anlatici",metin:"Doktor Teyze bu kez Kino’nun kalbini dinledi. Sonra kulaklığı onun kulaklarına yerleştirip yuvarlak ucu göğsünde tuttu. Kino’nun gözleri büyüdü."},{kim:"kino",metin:"Güm güm! Anne, içimde küçük bir davul var!"},{kim:"anlatici",metin:"Bir süre hiç konuşmadı. Bir daha duymak istiyordu. Güm güm. Güm güm."}]},{no:9,ad:"Kocaman bir aaa",renk:"#F6DAB2",tarif:"Doktor Teyze küçük ışığını tutarken Kino ağzını açıyor.",satirlar:[{kim:"anlatici",metin:"Doktor Teyze küçük ışığını önce kendi avucuna tuttu. Kino ışığın yuvarlak izini görünce ağzını açtı."},{kim:"kino",metin:"Aaaa!"},{kim:"anlatici",metin:"Doktor Teyze diline ve boğazına baktı. Işık söndüğünde Kino’nun sesi hâlâ sürüyordu."},{kim:"kino",metin:"Aa… Bitti mi? Ben daha söyleyecektim!"}]},{no:10,ad:"Kıpır kıpır bir karın",renk:"#F6DAB2",tarif:"Kino’nun karnı nazikçe muayene edilirken Kino ve Bulut gülüyor.",satirlar:[{kim:"anlatici",metin:"Sıra karnına gelince doktor önce ellerini birbirine sürtüp ısıttı. Kino tişörtünü biraz yukarı çekti. Doktorun eli karnına hafifçe değince burnu kıpırdadı."},{kim:"kino",metin:"Bekleyin! Tam orası gıdıklanıyor!"},{kim:"anlatici",metin:"Doktor elini çekip bekledi. Kino kahkahasını bitirince başıyla işaret etti."},{kim:"kino",metin:"Tamam, şimdi bakabilirsiniz."}]},{no:11,ad:"İki küçük yıldız",renk:"#F6DAB2",tarif:"Kino, kendi yıldızının eşini Kuzu’nun kırmızı kurdelesinin altına yapıştırıyor.",satirlar:[{kim:"anlatici",metin:"Kontrol bitmişti. Kino kendine sarı bir yıldız seçti. Doktor Teyze kutuyu kapatacakken Kino, Kuzu’nun boş göğsünü gösterdi."},{kim:"kino",metin:"Ama ilk hasta oydu!"},{kim:"anlatici",metin:"Doktor kutuyu yeniden uzattı. Kino ikinci yıldızı kırmızı kurdelenin altına bastırdı. Bu yıldız Kuzu’yla birlikte Lokum’a gidecekti."}]},{no:12,ad:"Bir kalp daha",renk:"#F6DAB2",tarif:"Kino kapıda annesinin kalbini dinliyor.",satirlar:[{kim:"anne",metin:"Hadi Kino, evimize gidiyoruz!"},{kim:"anlatici",metin:"Kino bu kez kapıdan çıkarken durdu. Oyuncak kulaklığını çıkardı. Annesi eğilince yuvarlak ucunu hırkasına dayadı."},{kim:"kino",metin:"Seninkini de dinleyeyim. Belki aynı şarkıyı çalıyorlardır."},{kim:"anlatici",metin:"Annesi gülümsedi. Kino başını onun göğsüne yaslayıp bir de öyle dinledi."}]},{no:13,ad:"Söz, yanındayım",renk:"#F6DAB2",tarif:"Lokum yıldızlı Kuzu’ya sarılıyor. Kino kardeşinin yanına diz çöküp ona sarılıyor.",satirlar:[{kim:"anlatici",metin:"Evde Lokum, Kuzu’yu görünce iki kolunu birden açtı. Önce kırmızı kurdelesini, sonra yıldızını okşadı."},{kim:"lokum",metin:"Kuzu korktu mu?"},{kim:"kino",metin:"Başta biraz. Ben onun yanında kaldım. İstersen sana da göstereyim."},{kim:"anlatici",metin:"Lokum, Kuzu’yu bağrına bastı. Kino da yanına diz çöküp ikisini birden kucakladı."},{kim:"kino",metin:"Önce tık tık. Sonra aaa. Sonra kocaman bir sarılma!"}]}],L={baslik:"Kino’yu ne rahatlattı?",sorular:["Kino kapıda beklerken neyi bilmek istedi?","Doktor küçük ışığı önce nereye tuttu?","Sen Kuzu’ya sırada ne olduğunu nasıl anlatırdın?"],not:"Bir oyuncak seçip sırayla doktor ve hasta olabilirsiniz."},l={id:h,baslik:D,kapak:A,sayfalar:_,ebeveyn:L},M="kurabiye",S="Kino Kurabiye Yapıyor",T={renk:"#f6dd99",tarif:"Kino yıldız kurabiyesini, Lokum da kendi yaptığı yuvarlak kurabiyeyi gösteriyor.",satirlar:[{kim:"anlatici",metin:"Kino Kurabiye Yapıyor."}]},w=[{no:1,ad:"Pencereye vuran yağmur",renk:"#efe3ba",tarif:"Kino başını yağmurlu pencereden mutfak kapısına çeviriyor. Annesi karıştırma kâsesini çıkarıyor.",satirlar:[{kim:"anlatici",metin:"Kino, camdaki iki yağmur damlasını yarıştırıyordu. Biri aşağıya indi. Öteki yerinden kıpırdamadı. Derken mutfaktan bir tıkırtı geldi. Annesi en büyük kâseyi çıkarmıştı. Yanında da yıldız biçiminde bir kalıp vardı."},{kim:"kino",metin:"Anne, kurabiye mi yapıyorsun? Ben de yapabilir miyim?"},{kim:"anne",metin:"Gel, baş aşçım. Önce ellerimizi yıkayalım."}]},{no:2,ad:"İki küçük aşçı",renk:"#efe3ba",tarif:"Annesi, taburesine çıkan Kino’nun önlüğünü bağlıyor. Lokum’un önünde küçük bir kâse ve bardak var.",satirlar:[{kim:"anlatici",metin:"Kino ellerini kurulayıp taburesini tezgâha çekti. Annesi sarı önlüğün bağlarını belinde düğümledi. Lokum da mama sandalyesinden iki elini uzattı."},{kim:"lokum",metin:"Ben de! Lokum da aşçı!"},{kim:"anlatici",metin:"Annesi onun önüne küçük bir kâseyle mavi bardağını koydu. Kino önlüğünü düzeltti."},{kim:"kino",metin:"Unu ben koyayım anne. Tek başıma yapabilirim!"}]},{no:3,ad:"Burnunun ucunda",renk:"#efe3ba",tarif:"Kino’nun bardağından kâseye dökülen un burnuna sıçrıyor. Lokum gülüyor.",satirlar:[{kim:"anne",metin:"Bardağı kâseye yaklaştır, Kino. Sonra yavaşça dök."},{kim:"anlatici",metin:"Kino bardağı çoktan kaldırmıştı. Bir çevirişte bütün un kâseye boşaldı. Puf! Havaya kalkan unun bir tutamı burnunun ucuna kondu."},{kim:"lokum",metin:"Abi! Burnuna kar yağdı!"},{kim:"anlatici",metin:"Kino gözlerini kırpıştırdı. Annesinin tuttuğu çelik kâseye eğilince beyaz burnunu o da gördü. Gülüp burnunu sildi."}]},{no:4,ad:"Merdaneyi bırakmayan hamur",renk:"#efe3ba",tarif:"Kino merdaneyi kaldırınca hamurun bir ucu onunla birlikte yükseliyor.",satirlar:[{kim:"anlatici",metin:"Annesi malzemeleri karıştırıp hamuru paylaştırdı. Kino kendi parçasına merdaneyle bastırdı. Merdaneyi kaldırdı. Hamur da kalktı. Hamuru çekince bu kez başparmağına yapıştı."},{kim:"kino",metin:"Anne, bu beni bırakmıyor! Böyle nasıl yıldız yapacağım?"},{kim:"anlatici",metin:"Merdaneyi tezgâha bıraktı. Az önce unu tek başına dökmek isteyen Kino, bu kez annesine yer açtı."},{kim:"kino",metin:"Bana bir kere gösterir misin?"}]},{no:5,ad:"Bir tutam un",renk:"#efe3ba",tarif:"Kino, hafifçe unlanmış merdaneyi tek parça hamurun üstünde yuvarlıyor.",satirlar:[{kim:"anlatici",metin:"Annesi parmaklarının arasına bir tutam un aldı. Birazını Kino’nun ellerine, birazını da merdaneye serpti."},{kim:"anne",metin:"Şimdi hafifçe it. Sonra kendine doğru çek."},{kim:"anlatici",metin:"Kino merdaneyi ileri sürdü, geri çekti. Bir daha ileri, bir daha geri… Hamur her seferinde biraz daha yayıldı. Kino merdaneyi usulca kaldırdı. Hamur tezgâhta kaldı!"},{kim:"kino",metin:"Bak anne! Bu sefer beni bıraktı!"}]},{no:6,ad:"Lokum’un kalıbı",renk:"#efe3ba",tarif:"Kino yıldız kalıbını kullanıyor. Lokum mavi bardağını kaldırınca yuvarlak kurabiyesi görünüyor.",satirlar:[{kim:"anlatici",metin:"Kino sarı kalıbı bastırdı. Kaldırınca hamurda küçük bir yıldız kaldı. Yanına bir kalp, bir çam ağacı, bir yıldız daha sığdırdı. Lokum’un kalıbı yoktu. O da bardağını ters çevirip kendi hamuruna bastırdı."},{kim:"lokum",metin:"Abi, bak! Top yaptım!"},{kim:"anlatici",metin:"Bir yanı biraz yassı, tombul bir yuvarlaktı. Kino tepsinin önünde ona yer açtı."},{kim:"kino",metin:"Seninki burada dursun. Fırının camından da görürüz."}]},{no:7,ad:"Fırının küçük penceresi",renk:"#efe3ba",tarif:"Kino ile Mino kapalı fırının camından kurabiyeleri izliyor. Babası kapıdan bakıyor.",satirlar:[{kim:"anlatici",metin:"Annesi tepsiyi fırına sürdü. Kino taburesine oturup çenesini avuçlarına dayadı. Babasıyla Mino mutfağa geldiklerinde hâlâ aynı yere bakıyordu."},{kim:"kino",metin:"[whispers] Mino, şu yıldızı görüyor musun? Az önce böyle tombul değildi."},{kim:"mino",metin:"Öndeki de kabarmış! O yuvarlağı sen mi yaptın?"},{kim:"kino",metin:"Onu Lokum yaptı. Hem de bardakla!"}]},{no:8,ad:"Son kalıp",renk:"#efe3ba",tarif:"Babası tezgâhı siliyor. Kino sarı yıldız kalıbını köpüklü suya bırakıyor.",satirlar:[{kim:"baba",metin:"Kino, ben tezgâhı silsem kalıpları kim yıkar?"},{kim:"kino",metin:"Ben! Yıldızın köşelerinde hamur kalmış."},{kim:"anlatici",metin:"Babası ıslak bezle unu topladı. Kino kalıpları köpüklü suya daldırdı. Kalp tamam. Çam ağacı tamam. Yıldızın son köşesini de yıkadı. Tam o sırada fırının saati çaldı. Tıng!"},{kim:"kino",metin:"Duydun mu baba? Tam da işimiz bitti!"}]},{no:9,ad:"İlk ısırık",renk:"#efe3ba",tarif:"Lokum yuvarlak kurabiyesini, Mino kalbi tutuyor. Kino kendi yıldızından ilk ısırığı alıyor.",satirlar:[{kim:"anlatici",metin:"Annesi tepsiyi eldivenle çıkarıp kurabiyeleri soğumaya bıraktı. Tezgâhın öbür ucundan üç küçük ağız birden üfledi. Nihayet kurabiyeler ılıdı. Kino önce bir yanı yassı yuvarlağı buldu."},{kim:"kino",metin:"Bu senin, Lokum. Kalp de Mino’nun. Anne, baba, büyük yıldızı paylaşır mısınız?"},{kim:"anlatici",metin:"Kendine kalan yıldızın bir ucunu ısırdı. Kıtır! Lokum da yuvarlağından bir ısırık aldı. Sonra bardağını abisine doğru itti."},{kim:"lokum",metin:"Bir daha yapalım mı?"},{kim:"kino",metin:"Yapalım. Sen bardağını getir, ben yıldızımı!"}]}],E={baslik:"Birlikte hatırlayalım",sorular:["Kino merdaneyi ilk kaldırdığında ne oldu?","Lokum, kendi kurabiyesini hangi eşyayla şekillendirdi?","Senin yaptığın kurabiyeyi tabakta nasıl tanırdın?"],not:"Birlikte oyun hamurunu açıp evdeki küçük kalıplarla değişik izler çıkarabilirsiniz."},m={id:M,baslik:S,kapak:T,sayfalar:w,ebeveyn:E},F="alisveris",U="Kino Babasıyla Markette",C={renk:"#E9CF91",tarif:"Kino resimli listesini babasına gösteriyor. Küçük arabası marketin kapısında.",satirlar:[{kim:"anlatici",metin:"Kino Babasıyla Markette."}]},$=[{no:1,ad:"Üç küçük resim",renk:"#F0DFC3",tarif:"Annesi elma, süt ve ekmek çizdiği listeyi Kino’ya uzatıyor. Babası bez çantaları hazırlıyor.",satirlar:[{kim:"anlatici",metin:"Kahvaltıdan sonra babası ekmek sepetini kaldırdı. Dibinde birkaç kırıntı kalmıştı. Annesi de buzdolabında sütle elmanın yerini boş buldu."},{kim:"baba",metin:"Ben markete gidiyorum. Benimle kim gelir?"},{kim:"kino",metin:"Ben! Ama ne alacağımızı nasıl hatırlayacağım?"},{kim:"anlatici",metin:"Annesi bir kâğıda kırmızı bir elma çizdi. Altına bir kutu süt, en alta da bir ekmek. Kino parmağını üç resmin üstünde gezdirip kâğıdı cebine koydu."}]},{no:2,ad:"Bayraklı araba",renk:"#F0DFC3",tarif:"Kino kendine uygun küçük arabanın kolunu tutuyor. Lokum büyük arabanın çocuk koltuğunda.",satirlar:[{kim:"anlatici",metin:"Kapılar açılınca Kino iki sıra araba gördü. Büyüklerin kolları neredeyse omzuna geliyordu. Yanlarındaki küçük arabanınsa turuncu bir bayrağı vardı. Kino kolunu tuttu. Tam boyuna göreydi!"},{kim:"lokum",metin:"Düt düüt! Lokum da geliyor!"},{kim:"anlatici",metin:"Lokum babasının arabasındaki koltuğa kurulmuştu. Kino cebine hafifçe vurdu. Liste oradaydı."},{kim:"kino",metin:"Elmaları ben bulacağım. Peşimden gelin!"}]},{no:3,ad:"Üç portakal yolda",renk:"#F0DFC3",tarif:"Küçük araba alçak sepete dokunmuş. Üç portakal yere yuvarlanırken Kino duruyor, babası eğiliyor.",satirlar:[{kim:"anlatici",metin:"Kino arabasını hızlandırdı. Turuncu bayrak köşeyi döndü, ama arabanın önü alçak bir sepete dokundu. Tık! Üç portakal üç ayrı yöne yuvarlandı."},{kim:"lokum",metin:"Baba, bak! Toplar kaçtı!"},{kim:"anlatici",metin:"İlkini babası yakaladı. Kino ikincisini raftan, üçüncüsünü de küçük arabasının altından aldı. Portakalları sepete geri koydular."},{kim:"baba",metin:"Gel, şu köşeyi bu sefer yan yana yürüyerek dönelim."},{kim:"kino",metin:"Böyle daha kolay duruyor!"}]},{no:4,ad:"Beşinci elma",renk:"#F0DFC3",tarif:"Beş kırmızı elmanın poşeti terazide. Kino elma resimli düğmeye uzanıyor.",satirlar:[{kim:"anlatici",metin:"Kino listeyi açtı. İlk resmin tıpkısı karşı raftaydı. Babası poşetin ağzını açtı, Kino kırmızı elmaları birer birer içine bıraktı."},{kim:"kino",metin:"Bir anneme, bir babama, bir Lokum’a, bir Mino’ya… Beşincisi de bana!"},{kim:"baba",metin:"Şimdi tartalım. Sence hangi düğmeye basacağız?"},{kim:"anlatici",metin:"Kino terazideki elma resmini bulup bastı. Vızz, tık! Makinenin kenarından küçük, beyaz bir etiket çıktı."}]},{no:5,ad:"Beni bırakmıyor",renk:"#F0DFC3",tarif:"Beyaz etiket Kino’nun parmağına kıvrılmış. Kino kalkık patisine şaşkınlıkla bakıyor.",satirlar:[{kim:"anlatici",metin:"Kino etiketi çekti. Tam poşete götürürken bir köşesi kıvrılıp parmağına yapıştı. Öbür eliyle köşeyi kaldırdı. Bu kez de başparmağı etikete takıldı. Elini sallayınca etiket de onunla sallandı."},{kim:"kino",metin:"Baba, poşet burada, etiket burada. İkisini bir türlü buluşturamıyorum!"},{kim:"anlatici",metin:"Babası elini uzattı. Kino bu sefer parmaklarını kıpırdatmadan bekledi."}]},{no:6,ad:"İki ucundan",renk:"#F0DFC3",tarif:"Kino iki ucundan tuttuğu barkod etiketini elma poşetinin ortasına düz biçimde yapıştırıyor.",satirlar:[{kim:"anlatici",metin:"Babası kıvrılan kâğıdı yavaşça çıkardı. Poşet hâlâ terazideydi. Kino elma düğmesine bir daha bastı."},{kim:"baba",metin:"Bir köşesini bu elinle tut. Öbür köşesini de öteki elinle. Şimdi poşete yaklaştır."},{kim:"anlatici",metin:"Kino iki ucunu tuttu. Önce ortası poşete değdi. Sonra iki kenarını sıvazladı. Ellerini kaldırınca etiket olduğu yerde kaldı."},{kim:"kino",metin:"Baba, bak! Bu kez parmağım benimle geldi, etiket gelmedi!"}]},{no:7,ad:"Raftaki süt",renk:"#F0DFC3",tarif:"Babası Kino’yu kaldırıyor. Kino süt kutusuna uzanırken küçük arabada etiketli elma poşeti var.",satirlar:[{kim:"anlatici",metin:"Kino listedeki ikinci resmi buldu. Süt kutuları bir üst raftaydı. Ayaklarının ucuna yükseldi ama parmakları rafa ancak değdi."},{kim:"baba",metin:"Kucağıma gelmek ister misin?"},{kim:"anlatici",metin:"Babası onu kaldırınca Kino bir kutuyu iki eliyle aldı. Sütü elmaların yanına koydular. Fırın köşesinde de bir ekmeği kâğıt torbaya yerleştirdiler. Lokum burnunu torbaya yaklaştırdı."},{kim:"lokum",metin:"Mmm! Sıcak ekmek!"},{kim:"kino",metin:"Elma, süt, ekmek. Üçü de tamam!"}]},{no:8,ad:"O bip sesi",renk:"#F0DFC3",tarif:"Kino elma poşetinin etiketini kasa camına çeviriyor. Sütle ekmek bandın öbür ucunda.",satirlar:[{kim:"anlatici",metin:"Kino önce sütü, sonra ekmeği, en son elmaları siyah banda dizdi. Ellerini çekince üçü de kasaya doğru yola çıktı. Kasiyer abla sütle ekmeği okuttu. Elmaları Kino’ya bıraktı."},{kim:"kino",metin:"Benim yapıştırdığım etiketle mi?"},{kim:"anlatici",metin:"Kasiyer abla küçük camı gösterdi. Kino poşeti iki eliyle kaldırıp etiketi cama çevirdi. Bip!"},{kim:"kino",metin:"Duydun mu baba? O ses benim elmalardan geldi!"}]},{no:9,ad:"Kimin elması?",renk:"#F0DFC3",tarif:"Evde Kino, Mino ve Lokum yıkanmış kırmızı elmaları paylaşıyor. Küçük mavi bez çanta sandalyede.",satirlar:[{kim:"anlatici",metin:"Eve dönerken elmalar Kino’nun mavi bez çantasındaydı. Kapıda annesiyle Mino onları karşıladı. Kino listeyi annesine uzattı."},{kim:"kino",metin:"Üçüne de bakabilirsin anne. Hepsi burada!"},{kim:"anlatici",metin:"Elmaları birlikte yıkadılar. Kino ikisini anne babası için kâsede bıraktı. Sonra Mino’ya ve Lokum’a birer elma uzattı."},{kim:"mino",metin:"Beni de mi saydın?"},{kim:"kino",metin:"Tabii! Seninki dördüncüydü."},{kim:"anlatici",metin:"Kino beşinci elmadan bir ısırık aldı. Mutfakta bu kez bip sesi yerine kocaman bir kütür sesi duyuldu."}]}],R={baslik:"Birlikte hatırlayalım",sorular:["Kino okumadan listesine nasıl baktı?","Etiketi nasıl tutunca poşete yapıştırabildi?","Sen markete gidecek olsan listene hangi üç resmi çizerdin?"],not:"Birlikte üç eşyanın resmini çizip evde resimli listenizle alışveriş oyunu oynayabilirsiniz."},o={id:F,baslik:U,kapak:C,sayfalar:$,ebeveyn:R},H="ustkat",O="Üst Kata Kim Geldi?",P={renk:"#A3D7CD",tarif:"Çocuklar Bulut’un oyuncak kutusunu açıyor.",satirlar:[{kim:"anlatici",metin:"Üst Kata Kim Geldi?"}]},Y=[{no:1,ad:"Sokaktaki Büyük Kamyon",tarif:"Sabah Çınar Apartmanı’nın önünde duran büyük mavi nakliye kamyonu. İki görevli kamyonun arkasından kahverengi karton kolileri apartman kapısına taşıyor. Kino, Mino ve Lokum birinci kat balkonundan merakla aşağı bakıyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Cumartesi sabahı Çınar Apartmanı’nın önüne mavi bir kamyon yanaştı. Arka kapakları açılınca Kino balkona koştu. Kamyonun içi kahverengi kutularla doluydu."},{kim:"kino",metin:"Anne, bak! Bizim eve kutular geliyor!"},{kim:"anne",metin:"Üçüncü kata yeni komşularımız taşınıyor. Eşyalarını getirmişler."},{kim:"kino",metin:"Koca bir ev kutuların içine nasıl sığar ki?"}]},{no:2,ad:"Merdivendeki Yabancı Sesler",tarif:"Apartman merdiveni. Kino ve karşı komşusu Mino daire kapısını aralamış, üst kattan gelen ayak seslerini ve yankılanan konuşmaları dinliyor. Lokum da bacaklarının arasından başını uzatmış.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Öğlene kadar merdivenlerden pat-pat ayak sesleri geldi. Üst katın kapısı her açıldığında içeriden boş oda yankısı duyuluyordu."},{kim:"mino",metin:"Ben merdivenden çıkarken gördüm! Bizim boyumuzda, beyaz yünlü bir çocuk da var. Ama hiç konuşmadı, hemen kapının arkasına geçti."},{kim:"lokum",metin:"Kutu çocuk!"},{kim:"kino",metin:"Neden saklandı acaba? Bizim apartmanı sevmedi mi?"}]},{no:3,ad:"Hoş Geldin Tabağı",tarif:"Mutfak. Anne Defne ve Babaanne Nazlı çiçek desenli porselen bir tabağa ılık elmalı dilimler diziyor. Kino taburesine çıkmış tabağa bakıyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Mutfak tarçın kokuyordu. Babaanne Nazlı ile annesi, çiçekli tabağa ılık elmalı kek dilimlerini diziyordu."},{kim:"kino",metin:"Babaanne, bize misafir mi gelecek?"},{kim:"babaanne",metin:"Bugün misafir biziz. Düşünsene, insan taşındığı gün çatalının bile hangi kutuda olduğunu unutabilir. Hiç değilse keki hazır olsun."},{kim:"kino",metin:"Tabağı ben taşıyabilir miyim? İki elimle tutarım."}]},{no:4,ad:"Yankılanan Boş Salon",tarif:"Üçüncü katın kapısı açılmış. Yeni komşuları Pınar Teyze onları gülümseyerek karşılıyor. Arkadaki salonda henüz halı serilmemiş; her yerde birbirinin aynısı kapalı kahverengi koliler duruyor. Köşedeki bir kolinin üstünde Bulut tek başına oturuyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Üçüncü katta zili çaldılar. Pınar Teyze kapıyı açınca Kino çiçekli tabağı iki eliyle uzattı."},{kim:"kino",metin:"Hoş geldiniz! Tabağınız kolide kalmıştır diye size kek getirdik."},{kim:"anlatici",metin:"Pınar Teyze gülümseyip onları içeri buyur etti. Salonda henüz halı da perde de yoktu. Kino’nun adımları yankılandı. Bir kutunun üstünde beyaz yünlü bir çocuk oturuyordu."}]},{no:5,ad:"Birbirine Benzeyen Kutular",tarif:"Kino ve Mino, Bulut’un yanına yaklaşmış. Bulut’un elinde tek bir mavi oyuncak araba var ama etrafındaki bütün kahverengi kolilerin üstünde yalnızca yetişkin el yazısıyla siyah yazılar yazıyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Kino ile Mino yavaşça Bulut’un yanına yürüdüler. Bulut elindeki küçük mavi arabayı göğsüne bastırmıştı; kulakları düşüktü."},{kim:"kino",metin:"Merhaba, ben Kino. Alt katta oturuyorum. Bahçede arabalarımızı sürelim mi?"},{kim:"bulut",metin:"Benim öbür arabalarım ve tahta garajım kayboldu. Hepsi bu kahverengi kutuların içinde ama bütün kutular birbirinin aynısı!"},{kim:"anlatici",metin:"Kino etrafına baktı. Gerçekten de odadaki yirmi kutunun yirmisi de aynı renkti."}]},{no:6,ad:"Okunmayan Yazılar",tarif:"Mino bir kolinin üstündeki siyah el yazısını parmağıyla gösteriyor. Bulut ve Kino yazıya eğilip bakıyorlar ama ikisi de harfleri okuyamadığı için şaşkın duruyorlar.",renk:"#A3D7CD",satirlar:[{kim:"mino",metin:"Bak Bulut! Baban kutuların üstüne bir şeyler yazmış."},{kim:"bulut",metin:"Babam okuyunca kolay. Ama ben daha okuyamıyorum ki."},{kim:"anlatici",metin:"Kino da başını yana eğip harflere baktı. O da oyuncaklarla yastıkların kutusunu ayıramamıştı."},{kim:"bulut",metin:"Eski odamda garajım hep yatağımın yanındaydı. Burada nereye baksam kutu."}]},{no:7,ad:"Kino’nun Fikri",tarif:"Kino parmağını kaldırıp heyecanla Bulut’a ve Mino’ya bir şey anlatıyor. Lokum da en alttaki küçük bir kolinin kenarına tutunmuş.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Kino anaokulundaki askısını düşündü. Adını okuyamıyordu ama üstündeki küçük güneşi nerede görse tanırdı."},{kim:"kino",metin:"Bulut, oyuncak kutusuna araba çizsek? Üstünü görünce içini bilirsin!"},{kim:"bulut",metin:"Olur ama benim boyalarım da bir kutuda. Hangisinde, bilmiyorum."},{kim:"kino",metin:"Benimkiler alt katta. Sen araban için bir renk seç. Hemen geliyorum!"}]},{no:8,ad:"Kutu Kutuyu Açıyor",tarif:"Kino kendi odasından getirdiği renkli pastel boya kutusunu yere açmış. Pınar Teyze ilk kolinin bandını açıp içine bakarken Kino elinde kırmızı boyayla bekliyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Kino boya kutusuyla geri geldi. Kapağını açıp Bulut’un önüne koydu. Pınar Teyze de dizlerinin üstüne oturdu."},{kim:"kino",metin:"Siz yazıyı okur musunuz? Resmini biz yapacağız."},{kim:"anlatici",metin:"Pınar Teyze ilk kutunun üstündeki yazıyı parmağıyla izledi. Bulut’un oyuncakları!"},{kim:"bulut",metin:"Demek garajım burada! Kırmızıyı bana verir misin?"}]},{no:9,ad:"Kahverengi Kutudaki Kırmızı Araba",tarif:"Kino ve Bulut yan yana diz çökmüş, birinci kolinin dış yüzeyine kocaman bir kırmızı araba ve sarı bir top çiziyorlar.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Bulut kırmızı bir araba çizdi. Kino, yanına sarı bir top kondurdu. Pınar Teyze sıradaki kutuyu okudu. Bu kez yastıklarla battaniyelerin sırasıydı."},{kim:"mino",metin:"Bunu bana bırakın! Bir yastık, yanına da uykusu gelmiş bir ay…"},{kim:"bulut",metin:"Gözlerim kapalıyken bile yatağımı bulacağım neredeyse!"}]},{no:10,ad:"Lokum’un Terlik Kutusu",tarif:"Lokum kapının yanındaki alçak bir kolinin önüne oturmuş, mor boyayla kolinin üstüne iki tane küçük yuvarlak terlik şekli çiziyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Pınar Teyze kapının yanındaki kutuyu gösterdi. Terliklerle ayakkabılar oradaydı. Kutu öyle alçaktı ki Lokum oturduğu yerden önüne yetişiyordu."},{kim:"lokum",metin:"Teylik kutusu! Ben çizeceğim!"},{kim:"anlatici",metin:"Mor boyayı kavradı. İki terlik çizdi. Birinin burnu yukarı bakıyordu, ötekininki aşağı."},{kim:"bulut",metin:"Benim terliklerin biri yukarı kata, biri aşağı kata gidiyor!"}]},{no:11,ad:"Kutular Ev Oluyor",tarif:"Salonun ortasında artık üstü araba, yastık, kitap, tabak ve terlik resimleriyle bezeli neşeli koliler duruyor. Bulut araba resimli koliden tahta garajını çıkarmış, Kino ve Mino’yla halının üstüne kuruyor.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Bir süre sonra her kutunun tanıdık bir yüzü vardı. Birinde tabakla kaşık, birinde kitap, kapının yanında da Lokum’un ters terlikleri. Bulut doğruca kırmızı arabaya gitti."},{kim:"bulut",metin:"Garajımı kendim buldum!"},{kim:"anlatici",metin:"Tahta garajı yere koydu. Mavi arabası rampadan inerken üçü birden kornaya bastı. Düt düt! Bu kez yankıyı duyunca Bulut da güldü."}]},{no:12,ad:"Elmalı Kek Molası",tarif:"Balkon kapısının önünde yere serilen örtünün üstünde Anne Defne, Pınar Teyze ve dört çocuk Babaanne’nin çiçekli tabağındaki elmalı kekleri yiyorlar.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Kutuların resimleri bitince hepsi pencerenin önüne oturdu. Babaanne’nin gönderdiği çiçekli tabaktaki elmalı kekleri paylaştılar."},{kim:"bulut",metin:"Bu kek çok güzelmiş. Sizin apartmanda her gün böyle kek mi yeniyor?"},{kim:"kino",metin:"Her gün değil ama Babaannem alt katta oturuyor. Merdivenden inince kokusundan hemen anlarsın!"},{kim:"anlatici",metin:"Bulut ilk kez yeni evinin penceresinden aşağıdaki çınar ağacına gülümseyerek baktı."}]},{no:13,ad:"Kapı Çalınıyor",tarif:"Ertesi gün Kino’ların daire kapısı. Karşıda Bulut ve annesi Pınar Teyze duruyor; Bulut iki eliyle Babaanne’nin çiçekli tabağını tutuyor, tabağın içi parlak kırmızı eriklerle dolu.",renk:"#A3D7CD",satirlar:[{kim:"anlatici",metin:"Ertesi gün Kino’ların kapısı çaldı. Bulut ile annesi gelmişti. Bulut iki eliyle dünkü çiçekli tabağı tutuyordu. Bu kez tabakta kırmızı erikler vardı."},{kim:"bulut",metin:"Annem süzgeci arıyordu. Tabak resmini görünce mutfak kutusunu ona ben gösterdim. Erikleri beraber yıkadık!"},{kim:"kino",metin:"Anne! Tabağımızı getirmişler ama eriklerini içinde unutmuşlar!"}]},{no:14,ad:"Boş Gitmez, Boş Dönmez",tarif:"Apartman bahçesinde çınar ağacının altı. Kino, Mino, Bulut ve Lokum bankta yan yana oturmuş kırmızı eriklerini yerken yukarıdaki üçüncü katın perdeleri takılmış penceresine bakıyorlar.",renk:"#A3D7CD",satirlar:[{kim:"anne",metin:"Unutmadılar Kino. Bizim mahallede komşu tabağı boş gitmez, boş da dönmez."},{kim:"kino",metin:"Öyleyse erikler bitince biz de size bir şey getiririz!"},{kim:"bulut",metin:"Bu sefer sizi merdivende ben beklerim!"},{kim:"anlatici",metin:"Bahçede eriklerini yerken Kino üçüncü kata baktı. Dün o pencereyi bir kamyon dolusu kutudan tanıyordu. Bugün sarı perdenin arkasında kimin yaşadığını biliyordu. Elini kaldırıp Bulut’a bir erik daha uzattı."}]}],G="Üçüncü kata yirmi kahverengi kutu taşındı. Koca bir ev bu kutulara nasıl sığar? Peki Bulut içlerinden kendi evini nasıl bulacak?",j={baslik:"Birlikte hatırlayalım",sorular:["Bulut hangi kutunun kendisine ait olduğunu neden anlayamıyordu?","Sen oyuncak kutunun üzerine hangi resmi çizerdin?","Çiçekli tabak geri geldiğinde içinde ne vardı?"],not:"Bir çekmecenin içine birlikte bakın. İçindekileri anlatan küçük bir resim çizip çekmeceye asın."},d={id:H,baslik:O,kapak:P,sayfalar:Y,arkaKapak:G,ebeveyn:j},N="ucurtma",I="Kino Uçurtma Uçuruyor",x={renk:"#7fcad1",tarif:"Kino ile Lokum tepede uçurtma uçuruyor.",satirlar:[{kim:"anlatici",metin:"Kino Uçurtma Uçuruyor"}]},V=[{no:1,ad:"Sallanan Yapraklar",renk:"#75BDB0",tarif:"Salon penceresi. Dışarıdaki büyük çınar ağacının yaprakları rüzgârla bir yana eğilmiş. Babası dolabın üstünden kırmızı-sarı elmas biçimli uçurtmayı indirirken, Kino beyaz ip makarasını iki eliyle tutuyor.",satirlar:[{kim:"anlatici",metin:"Sabah pencerenin önündeki çınar ağacının dalları bir sağa, bir sola sallanıyordu. Kino camdan dışarı bakınca babası dolabın üstündeki kırmızı sarı uçurtmayı indirdi."},{kim:"kino",metin:"Baba, yapraklar hızlandı! Bugün uçurtmamız bulutlara kadar çıkar mı?"},{kim:"baba",metin:"Tam uçurtma havası. Makarayı sen taşı bakalım."},{kim:"anlatici",metin:"Kino beyaz makarayı iki eliyle kavradı. İpi parmağıyla yokladı; sıkı ve uzundu."}]},{no:2,ad:"Lokum’un Mavi Atkısı",renk:"#75BDB0",tarif:"Antrede ayakkabı giyiyorlar. Lokum bir koluna iki tur doladığı uzun, parlak mavi bir hediye kurdelesini Kino’nun uçurtmasına doğru uzatıyor.",satirlar:[{kim:"anlatici",metin:"Kapının önünde ayakkabılarını giyerken Lokum içeriden uzun, mavi bir kurdele getirdi. Yerde sürünmesin diye bir ucunu koluna iki kere dolamıştı."},{kim:"lokum",metin:"Abi, uçurtmaya atkı takalım mı? Yukarıda üşümesin."},{kim:"kino",metin:"Uçurtmalar üşümez ki Lokum! Hem bunu bağlarsak ağır gelir, uçamaz."},{kim:"anlatici",metin:"Kino kapıya yöneldi. Lokum mavi kurdelesini çözüp özenle avucunun içine topladı ve tulumunun cebine soktu."}]},{no:3,ad:"Tepedeki Buluşma",renk:"#75BDB0",tarif:"Geniş, çimenlik Çınar Tepesi. Mino ve üst kat komşuları kuzu Bulut çimenlerin üstünde Kino’ları karşılıyor. Kino uçurtmayı yere yatırmış, ipini açıyor.",satirlar:[{kim:"anlatici",metin:"Çınar Tepesi’ne çıktıklarında Mino ile Bulut onları bekliyordu. Tepede rüzgâr aşağıdakinden daha serindi."},{kim:"mino",metin:"Hadi Kino! En yükseğe çıktığında ipini bana da gösterir misin?"},{kim:"kino",metin:"Gösteririm! Ben şimdi koşunca hemen havalanacak."},{kim:"anlatici",metin:"Kino uçurtmayı çimenin üstüne bıraktı. Babasının yanına gelmesini beklemeden makarayı tutup yokuş aşağı koşmaya başladı."}]},{no:4,ad:"Çimende Gezen Uçurtma",renk:"#75BDB0",tarif:"Kino rüzgârla aynı yönde hızla koşuyor ama arkasındaki kırmızı uçurtma havalanmak yerine çimenlerin üstünde yatay biçimde kayarak sürükleniyor. Lokum gülerek uçurtmayı gösteriyor.",satirlar:[{kim:"anlatici",metin:"Kino rüzgârı arkasına alıp bütün hızıyla koştu. O koştu, kırmızı uçurtma da arkasından çimenlerin üstünde kaydı. Hışır, hışır!"},{kim:"lokum",metin:"Abi uçurtmayı gezdiriyor!"},{kim:"anlatici",metin:"Kino durup arkasına baktı. Kendisi nefes nefeseydi ama uçurtması yerden bir karış bile kalkmamıştı."},{kim:"kino",metin:"Baba, ben koşuyorum ama uçurtmam yerde yürüyor!"}]},{no:5,ad:"Rüzgâr Hangi Yanağında?",renk:"#75BDB0",tarif:"Baba, tepede Kino’nun yanında diz çöküyor. Kino gözlerini kapatıp esintiyi yüzünde hissediyor.",satirlar:[{kim:"anlatici",metin:"Babası gülümseyerek Kino’nun yanına geldi. Onu omuzlarından tutup olduğu yerde ters çevirdi."},{kim:"baba",metin:"Az önce rüzgârla aynı yöne koştun. Şimdi dur ve dinle bakalım, rüzgâr nereye değiyor?"},{kim:"anlatici",metin:"Serin bir esinti Kino’nun uzun kulaklarını geriye doğru havalandırdı."},{kim:"kino",metin:"Burnuma ve iki yanağıma değiyor!"},{kim:"baba",metin:"Şimdi bana dön. Rüzgâr senin arkandan bana doğru essin. Ben uçurtmayı kaldırınca ip gerilecek. Elindeki makarada hissedersin."}]},{no:6,ad:"İpin Ucundaki Tık-Tık",renk:"#75BDB0",tarif:"Baba ellerini açmış. Beyaz kâğıt kuyruklu uçurtma yükselirken Kino makarayı tutuyor.",satirlar:[{kim:"anlatici",metin:"Babası rüzgârın estiği yönde biraz uzaklaştı. Uçurtmayı iki eliyle kaldırdı. Kino ip gerilince başıyla işaret verdi. Babası ellerini açtı. Kırmızı sarı uçurtma beyaz kuyruğunu peşinden sürükleyerek yükseldi."},{kim:"bulut",metin:"Bakın! Ağaçların boyunu geçti!"},{kim:"anlatici",metin:"İp gerildikçe Kino’nun elindeki makara hafifçe çekiliyordu."},{kim:"kino",metin:"Baba, ipi elimde tık-tık ediyor! Yukarıda canlı gibi duruyor!"}]},{no:7,ad:"Böğürtlen Çalısının Dalı",renk:"#75BDB0",tarif:"Rüzgâr sertleşmiş; uçurtma biraz alçalırken altındaki ince kağıt kuyruk tepenin kenarındaki böğürtlen çalısının dalına takılıp kopuyor.",satirlar:[{kim:"anlatici",metin:"Mino ile Bulut uçurtmanın gölgesini kovalarken tepeden ani bir rüzgâr esti. Kırmızı uçurtma bir an yana süzülüp böğürtlen çalısının üstünden geçti. Cırt! Uçurtmanın altındaki kağıt kuyruk çalının dalına takılıp koptu."},{kim:"mino",metin:"Kino, kuyruğu çalıda kaldı!"},{kim:"kino",metin:"Olsun! Kanatları sağlam, yine uçar."}]},{no:8,ad:"Başı Dönen Uçurtma",renk:"#75BDB0",tarif:"Kuyruksuz kalan kırmızı uçurtma havada düz duramıyor; gökyüzünde fırıl fırıl dönerek daireler çiziyor ve çimenlerin üstüne yan yatıyor.",satirlar:[{kim:"anlatici",metin:"Kuyruksuz kalan uçurtma yeniden yükseldi. Ama bu kez gökyüzünde düz duramadı. Önce sağa yattı, sonra fırıl fırıl iki daire çizip çimenlerin üstüne indi."},{kim:"kino",metin:"Baba, uçurtmamın başı döndü! Neden yukarı bakmıyor?"},{kim:"anlatici",metin:"Babası çalıda kalan kağıt parçasını gösterdi."},{kim:"baba",metin:"Uçurtmayı havada dengede tutan şey kuyruğuydu Kino. Arkasında hafif bir ağırlık olmayınca hangi tarafa duracağını şaşırıyor."}]},{no:9,ad:"Ağır Gelen Dal",renk:"#75BDB0",tarif:"Çimenlerin üstünde Kino, Mino ve Bulut uçurtmanın alt halkasının başına toplanmış. Mino yerde bulduğu kuru bir ağaç dalını uçurtmanın ucuna tutuyor; Bulut da bir tutam çimen uzatıyor.",satirlar:[{kim:"anlatici",metin:"Çocuklar uçurtmanın başına çömeldi. Mino yerden bulduğu kuru bir dalı uçurtmanın altındaki halkaya geçirdi."},{kim:"mino",metin:"Bu dal çalıya takılsa da kopmaz!"},{kim:"anlatici",metin:"Kino ipi çekti. Ama kuru dal öyle ağırdı ki uçurtmanın burnu bile yerden kalkmadı."},{kim:"bulut",metin:"Bu kuyruk uçurtmadan daha ağır oldu!"}]},{no:10,ad:"Uçuşan Çimenler",renk:"#75BDB0",tarif:"Kino uçurtmanın alt ipine uzun çimen sapları sıkıştırmış ama rüzgâr esince çimenler uçuşup yere dökülüyor. Kino şaşkınlıkla boş kalan halkaya bakıyor.",satirlar:[{kim:"anlatici",metin:"Bu kez Kino yerden uzun çimenler topladı. İpin ucuna sıkıştırdı. Ama uçurtmayı kaldırır kaldırmaz rüzgâr esti ve çimenler tek tek uçup dağıldı."},{kim:"kino",metin:"Dal çok ağır geliyor, çimen de hemen düşüyor. Bize hem uzun hem de uçacak kadar hafif bir şey lazım."},{kim:"anlatici",metin:"Kino etrafına bakındı. Tepede çimenden ve taştan başka bir şey görünmüyordu."}]},{no:11,ad:"Cebinden Çıkan Rüzgâr",renk:"#75BDB0",tarif:"Lokum tulumunun cebinden sabahki uzun mavi kurdeleyi çıkarmış, elini havaya kaldırmış. Mavi kurdele rüzgârda yumuşak bir dalga gibi havada süzülüyor. Kino, Mino ve Bulut kurdeleye bakıyor.",satirlar:[{kim:"anlatici",metin:"Tam o sırada Lokum elini cebine attı. Sabah evden çıkarken getirdiği mavi kurdeleyi çıkardı. Ucunu havaya kaldırınca kurdele rüzgârda su gibi dalgalandı."},{kim:"lokum",metin:"Bak abi. Benim atkım tek başına bile uçuyor!"},{kim:"anlatici",metin:"Kino rüzgârda tüy gibi yüzen mavi şeride baktı. Sabah ağır gelir diye istemediği kurdele, şimdi tam aradıkları boydaydı."},{kim:"kino",metin:"Lokum! Sabah bana bunu vermiştin, ben almamıştım. Uçurtmamıza senin atkını kuyruk yapalım mı?"}]},{no:12,ad:"Mavi Kuyruğun Düğümü",renk:"#75BDB0",tarif:"Kino ile Lokum çimenlerde uçurtmanın yanındalar. Mavi kurdele uçurtmanın alt ucuna bağlanmış.",satirlar:[{kim:"lokum",metin:"Üşümesin diye mi?"},{kim:"kino",metin:"Başı dönmesin diye!"},{kim:"anlatici",metin:"Lokum mavi kurdeleyi iki eliyle abisine uzattı. Kino kurdelenin ucunu uçurtmanın altındaki halkadan geçirdi, babası da sağlam bir ilmek attı. Mavi kurdele çimenlerin üstünde upuzun uzandı."},{kim:"bulut",metin:"Bu sefer uçurtmayı ben tutayım, Kino. İp gerilince bana seslen!"}]},{no:13,ad:"Makaranın İki Ucu",renk:"#75BDB0",tarif:"Kino ile Lokum aynı makarayı tutuyor. Yukarıda kırmızı sarı uçurtmanın uzun mavi kuyruğu dalgalanıyor.",satirlar:[{kim:"anlatici",metin:"Bulut uçurtmayı başının üstüne kaldırdı. Kino ipteki çekişi hissedince seslendi. Bulut ellerini açtı. Uçurtma yükseldi, mavi kuyruğu ardından dalgalandı. Bu kez hiç takla atmadı. Kino yanında gökyüzüne bakan Lokum’a sokuldu. Makarada küçücük bir patiye daha yer vardı."},{kim:"kino",metin:"Senin atkın olmasa uçamazdı. Bir ucundan da sen tut!"},{kim:"anlatici",metin:"İp rüzgârda gerildikçe Lokum’un küçük elleri hafifçe titredi."},{kim:"lokum",metin:"Abi, uçurtma bana tık-tık yapıyor!"}]},{no:14,ad:"Başı Dönmeyen Uçurtma",renk:"#75BDB0",tarif:"Akşamüstü Çınar Apartmanı’nın giriş kapısı. Babası, Kino, Mino, Bulut ve Lokum eve dönüyor. Kino’nun kucağındaki uçurtmanın altından mavi kurdele hâlâ bağlı duruyor; Lokum kurdelenin ucunu tutuyor.",satirlar:[{kim:"anlatici",metin:"Akşamüstü eve dönerken Kino ipi makaraya sardı ama mavi kurdeleyi uçurtmanın ucundan çözmedi. Apartman kapısından girerken babası gülümsedi."},{kim:"baba",metin:"Demek uçurtmalar da atkı takarmış, öyle mi Kino?"},{kim:"kino",metin:"Üşüdüğü için değil baba. Başı dönmesin diye!"},{kim:"lokum",metin:"Hiç dönmedi!"},{kim:"anlatici",metin:"Kino merdivenleri çıkarken mavi kurdelenin ucuna dokundu. Bugün uçurtmayı gökyüzüne çıkaran rüzgârdı; ama orada dümdüz tutan Lokum’un kurdelesiydi."}]}],X="Kino’nun uçurtması çimende geziyor, havada takla atıyor. Lokum’un cebindeyse sabah kimsenin istemediği mavi bir kurdele var. Acaba rüzgâr onu sevecek mi?",Z={baslik:"Birlikte hatırlayalım",sorular:["Kino ip gerildiğinde elinde ne hissetti?","Kuyruğu kopunca uçurtmanın uçuşu nasıl değişti?","Kino sabah istemediği kurdeleye tepede bakınca ne fark etti?"],not:"Dışarıda birlikte durun. İnce bir kâğıt şeridi havaya tutup rüzgârın onu hangi yana taşıdığını izleyin."},s={id:N,baslik:I,kapak:x,sayfalar:V,arkaKapak:X,ebeveyn:Z},q="kumkale",Q="Kino Kumdan Kale Yapıyor",J={renk:"#90D9D7",tarif:"Kino, Mino ve Lokum dört kuleli kalelerinin yanında.",satirlar:[{kim:"anlatici",metin:"Kino Kumdan Kale Yapıyor."}]},W=[{no:1,ad:"Kaptansız kayık",renk:"#90D9D7",tarif:"Deniz kenarı. Babası çizgili plaj şemsiyesini kuma sabitleyip açarken, Kino plaj çantasından çıkardığı kırmızı kovası ve sarı küreğinin yanında küçük mavi yelkenli kayığını kumun üstünde itmeye çalışıyor.",satirlar:[{kim:"anlatici",metin:"Babası şemsiyeyi açarken Kino mavi kayığını kuma indirdi. Bir itti, bir daha itti. Kayığın burnu kuma gömüldü. Arkasından Lokum’un sesi geldi."},{kim:"lokum",metin:"Ben kaptan olabilir miyim abi?"},{kim:"kino",metin:"Olursun! Ben sana kalesi olan bir liman yapacağım. İlk kayığı da sen yüzdüreceksin."}]},{no:2,ad:"Dört beyaz kabuk",renk:"#90D9D7",tarif:"Şemsiyenin gölgesinde Kino elleriyle kumu düzleştiriyor. Küçük kardeşi Lokum bir elinde küçük yeşil kum kalıbı, öbür avucunda beyaz deniz kabuklarıyla abisinin yanına oturuyor.",satirlar:[{kim:"anlatici",metin:"Lokum bir avucunda yeşil kalıbını, öbüründe dört kabuğu getirdi. Üçü avucuna sığmıştı. Dördüncüsünü düşmesin diye çenesiyle tutuyordu."},{kim:"lokum",metin:"Kaptanın getirdikleri!"},{kim:"kino",metin:"Her kuleye bir kabuk. Böylece kayığın denizden dönünce limanı tanır."}]},{no:3,ad:"Kumun üstündeki çizgi",renk:"#90D9D7",tarif:"Kino limanın çevresini kuma çiziyor. Lokum kabuğunu uzatıyor.",satirlar:[{kim:"anlatici",metin:"Kino küreğinin ucuyla kuma kocaman bir halka çizdi. Lokum bir kabuğu denizden halkaya doğru sürdü. Kabuğunun arkasında ince bir çizgi kaldı."},{kim:"lokum",metin:"Kayık buradan girsin mi?"},{kim:"kino",metin:"Önce kuleler, kaptan!"},{kim:"anlatici",metin:"Kino kuleye yer açarken Lokum’un çizgisini diziyle sildi. Lokum kabuğu alıp yanına koydu."}]},{no:4,ad:"Koşan Kova, Dökülen Su!",renk:"#90D9D7",tarif:"Kino deniz kıyısından kırmızı kovayla koşarak gelirken kova sağa sola sallanıyor; içindeki sular yol boyunca şıpır şıpır Kino’nun ayaklarına ve kuma dökülüyor. Lokum gülerek abisini gösteriyor.",satirlar:[{kim:"baba",metin:"Kule yapmak için kumu biraz ıslatalım."},{kim:"anlatici",metin:"Kino kovayı kıyıda doldurdu. Dönerken koşunca su ayaklarına sıçradı. Şıp, şıp, şılap! Şemsiyeye vardığında kovada bir yudum su kalmıştı."},{kim:"lokum",metin:"Abi ayaklarını yıkadı!"},{kim:"kino",metin:"Kovam benden hızlı koştu! Bir de kuru kumla deneyeyim."}]},{no:5,ad:"Dağılan Kuru Kum",renk:"#90D9D7",tarif:"Kino kırmızı kovayı ters çevirip tek eliyle yukarı kaldırmış; ama kuru sarı kumlar kule olmak yerine iki yana un gibi dağılıp alçak bir tepecik olmuş. Kino şaşkınlıkla elindeki boş kovaya bakıyor.",satirlar:[{kim:"anlatici",metin:"Kino kovayı kuru kumla doldurdu, ters çevirdi ve kaldırdı. Fısss! Kum iki yana yayıldı. Bir daha denedi. Bu kez de karşısında yassı bir tepecik vardı."},{kim:"kino",metin:"Baba, benim kovam kule yapmıyor!"},{kim:"anlatici",metin:"Kovanın içine baktı. Dibi de sağlamdı. Peki kule nereye gitmişti?"}]},{no:6,ad:'Islak Kum ve "Tık-Tık" Sırrı',renk:"#90D9D7",tarif:'Babası kumun üstüne su döküp ıslatmış. Kino ters çevirdiği kırmızı kovanın dibine sarı küreğiyle "tık-tık" vuruyor; yanında ilk sağlam kum kulesi dimdik duruyor.',satirlar:[{kim:"anlatici",metin:"Babası biraz su getirip kumu ıslattı. Kino nemli kumu kovaya doldurdu, avucuyla sıkıca bastırdı."},{kim:"baba",metin:"Şimdi ters çevir. Dibine küreğinle iki kere vur. Sonra iki elinle dümdüz yukarı kaldır."},{kim:"anlatici",metin:"Tık, tık! Kino kovayı kaldırınca altında bir kule duruyordu."},{kim:"kino",metin:"Baba, bak! Bu sefer ayakta kaldı!"}]},{no:7,ad:"Dört Kule, Dört Beyaz Bayrak",renk:"#90D9D7",tarif:"Dört köşesinde dört sağlam kule olan kumdan kale tamamlanmış. Lokum ortadaki küçük kapı kulesinin önüne oturmuş, dört büyük kulenin tepesine birer beyaz deniz kabuğu koyuyor.",satirlar:[{kim:"anlatici",metin:"Kino üç kule daha yaptı. Dört kulenin arasını nemli kumdan duvarlarla birleştirdi. Lokum yeşil kalıbıyla ön duvara küçük bir kapı yaptı. Sonra her kuleye bir kabuk kondurdu."},{kim:"lokum",metin:"Bak abi, şapka taktım!"},{kim:"kino",metin:"Uzaktan da dört beyaz bayrak gibi görünüyorlar!"}]},{no:8,ad:"Kaptan neyi bekliyor?",renk:"#90D9D7",tarif:"Kino kuru kumdaki kaleyi ve küçük yelkenliyi gösteriyor.",satirlar:[{kim:"kino",metin:"İşte limanın hazır, kaptan!"},{kim:"anlatici",metin:"Lokum kayığını kapının önüne bıraktı. Yelken rüzgârda titredi ama kayık olduğu yerde kaldı. Lokum bir kaleye, bir denize baktı."},{kim:"lokum",metin:"Abi, kuleler geldi de deniz ne zaman gelecek?"},{kim:"anlatici",metin:"Kino ilk kez kaleye Lokum’un oturduğu yerden baktı. Dört güzel kulesi vardı. Ama limanında bir damla su yoktu."}]},{no:9,ad:"İki kürek",renk:"#90D9D7",tarif:"Kino ve Mino kalenin çevresinde bir hendek kazıyor.",satirlar:[{kim:"anlatici",metin:"Mino mavi küreğiyle yanlarına geldi. Kino ona kuru kumdaki kayığı gösterdi."},{kim:"kino",metin:"Lokum’a liman sözü verdim. Bir ucundan tutar mısın?"},{kim:"mino",metin:"Ben soldan kazayım, sen sağdan. Ortada buluşuruz!"},{kim:"anlatici",metin:"İki kürek kalenin çevresini dolaştı. Uçları birbirine değince çıkan ses, iki arkadaşın da hoşuna gitti. Tık!"}]},{no:10,ad:"Gelmeyen su",renk:"#90D9D7",tarif:"Dalga kuru hendeğe ulaşmadan aradaki kum sırtında duruyor.",satirlar:[{kim:"anlatici",metin:"Kino ile Mino küreklerini bırakıp bekledi. Küçük bir dalga kıyıya geldi, durdu, geri çekildi. Açtıkları hendek hâlâ kuruydu."},{kim:"kino",metin:"Bir tur daha mı kazsak?"},{kim:"mino",metin:"Aynı yeri iki kere dolaşınca denize yaklaşmış olur muyuz?"},{kim:"anlatici",metin:"Lokum çoktan suyun durduğu yere çömelmişti. İlk kuleden bir kabuk ödünç aldı."}]},{no:11,ad:"Kabuğun peşinden",renk:"#90D9D7",tarif:"Lokum kabuğuyla kıyıdaki nemli kuma ince bir çizgi çekiyor.",satirlar:[{kim:"anlatici",metin:"Lokum kabuğu ıslak kumun üstünde kendine doğru çekti. Açtığı minicik izin peşinden bir parmak su yürüdü. Kino da çömeldi."},{kim:"lokum",metin:"Bak abi. Su buraya kadar beni takip etti."},{kim:"kino",metin:"Sabah da bana bu yolu gösteriyordun! Ben üstüne oturdum. Bir daha çizer misin?"},{kim:"anlatici",metin:"Bu kez Kino küreğini dizlerine yatırdı. Lokum’un çizgisini sonuna kadar izledi."}]},{no:12,ad:"Limanın ağzı",renk:"#90D9D7",tarif:"Kino ve Mino, Lokum’un işaretlediği girişteki son kum parçasını kaldırıyor.",satirlar:[{kim:"anlatici",metin:"Çizginin bir ucu denize, öbür ucu hendeğe dayanıyordu. Arada yalnızca bir küreklik kum vardı."},{kim:"kino",metin:"Kaptan, girişin yeri burası mı?"},{kim:"lokum",metin:"Tam orası!"},{kim:"anlatici",metin:"Mino yolun iki yanını açtı. Kino ortadaki son kumu kaldırdı. Yeni dalga kıyıya uzanınca su, açılan aralıktan usulca içeri girdi. Lokum kabuğunu kulesine geri koydu."}]},{no:13,ad:"İlk sefer",renk:"#90D9D7",tarif:"Lokum mavi kayığı suya bırakıyor. Kino yanında ilk seferi izliyor.",satirlar:[{kim:"anlatici",metin:"Kino kayığı alıp suya uzandı. Sonra durdu. Kayığı sapasağlam, iki eliyle Lokum’a verdi."},{kim:"kino",metin:"İlk seferi kim yapacaktı, hatırladın mı?"},{kim:"lokum",metin:"Kaptan Lokum!"},{kim:"anlatici",metin:"Lokum kıçına küçücük bir dokunuş yaptı. Mavi kayık, beyaz kabuklu kulelerin önünden süzüldü. Dar girişten geçerken kimsenin onu kaldırması gerekmedi."}]},{no:14,ad:"Kovaya sığan liman",renk:"#90D9D7",tarif:"Akşamüstü güneş alçalırken plajdan ayrılıyorlar. Kino bir elinde içinde mavi kayığı ve deniz kabukları olan kırmızı kovasını tutuyor, öbür elindeki sarı küreğiyle kovaya hafifçe vurarak babasına gülümsüyor.",satirlar:[{kim:"anlatici",metin:"Akşam kovaya dört kabuk, bir kürek ve bir kayık sığdı. Kale kumsalda kaldı. Babası şemsiyeyi kapatırken Kino’ya döndü."},{kim:"baba",metin:"Yarın yine bir liman yapsanız, nereden başlarsınız?"},{kim:"kino",metin:"Önce kaptana girişin nerede olacağını sorarım."},{kim:"lokum",metin:"Ben de sana kule için iki kere vurmayı hatırlatırım!"},{kim:"anlatici",metin:"Lokum kovaya vurdu. Tık! Kino küreğiyle karşılık verdi. Tık!"}]}],aa={baslik:"Birlikte hatırlayalım",sorular:["Kino ile Mino hendek kazınca su neden hemen gelmedi?","Lokum, kabuğuyla neyi gösterdi?","Kino en sonunda Lokum’a verdiği hangi sözü tuttu?"],not:"Bir avuç kuru kumla bir avuç nemli kumu iki küçük kaba bastırın. Kapları ters çevirince çıkan şekillere birlikte bakın."},ia="Dört kule hazır. Dört beyaz bayrak yerinde. Öyleyse Kaptan Lokum’un kayığı neden hâlâ kumda?",y={id:q,baslik:Q,kapak:J,sayfalar:W,ebeveyn:aa,arkaKapak:ia},na="cadir",ea="Kino Salonda Çadır Kuruyor",ka={renk:"#C4DEEE",tarif:"Kino, Mino ve Lokum mavi çarşafın altından bakıyor.",satirlar:[{kim:"anlatici",metin:"Kino Salonda Çadır Kuruyor."}]},ra=[{no:1,ad:"Hazır Çanta, Yağmurlu Cam",renk:"#C4DEEE",tarif:"Kino sırtında küçük çantasıyla pencerenin önünde duruyor; dışarıda yağmur başlamış. Babası dolaptan açık mavi büyük bir çarşafla küçük bir mandal sepeti çıkarıyor.",satirlar:[{kim:"anlatici",metin:"Kino sabah erkenden küçük sırt çantasını hazırlamıştı. İçine el fenerini ve dilimlenmiş elmalarını bile koymuştu. Mino’yla parkta çadır oyunu oynayacaklardı. Ama tam kapıya yöneldiğinde cama iri yağmur damlaları vurmaya başladı."},{kim:"kino",metin:"Baba, yağmur başladı! Şimdi çadırımızı nereye kuracağız?"},{kim:"anlatici",metin:"Babası dolaptan açık mavi, kocaman bir çarşafla küçük bir mandal sepeti çıkardı."},{kim:"baba",metin:"Park ıslaksa, biz de çadırımızı salona kurarız."}]},{no:2,ad:"Dört Sandalye, Bir Sarı Minder",renk:"#C4DEEE",tarif:"Babası ile Kino salonda dört ahşap sandalyeyi sırt sırta diziyor. Lokum yerde yuvarlak sarı bir minderi iki eliyle çekerek getiriyor.",satirlar:[{kim:"anlatici",metin:"Babasıyla Kino yemek masasının dört sandalyesini halının ortasına taşıdılar. Sandalyeleri sırtları birbirine bakacak biçimde karşılıklı dizdiler. Lokum da koltuğun kenarındaki yuvarlak sarı minderi kucaklayıp halıda sürükledi."},{kim:"lokum",metin:"Lokum da kamp! Minder geldi!"},{kim:"anlatici",metin:"Kino sarı minderi sandalyelerin tam ortasına yerleştirdi. Sonra mavi çarşafı kucağına aldı."},{kim:"kino",metin:"Çarşafı ben örteceğim baba. Tek başıma atabilirim!"}]},{no:3,ad:"Mavi Bulut Kimin Başında?",renk:"#C4DEEE",tarif:"Kino çarşafı yukarı savurmuş ama mavi çarşaf sandalyeler yerine Kino’nun kendi başının ve Lokum’un üstüne inmiş. Kino’nun yalnız burnu ve bir kulağı dışarıda, Lokum gülüyor.",satirlar:[{kim:"baba",metin:"Bir ucunu sen tut, Kino. Öbür ucunu da ben alayım."},{kim:"anlatici",metin:"Ama Kino kollarını çoktan havaya savurmuştu. Mavi çarşaf balon gibi şişti, yükseldi… Sonra sandalyelerin yerine doğruca Kino’nun başının üstüne indi!"},{kim:"lokum",metin:"Abi kayboldu! Abi çadır oldu!"},{kim:"anlatici",metin:"Kino çarşafın altından burnunu çıkardı. Başının üstündeki mavi kumaşa bakınca o da gülmeye başladı."},{kim:"kino",metin:"Çarşaf beni çadır sandı galiba!"}]},{no:4,ad:"Bir Ucunu Çekince",renk:"#C4DEEE",tarif:"Çarşaf dört sandalyenin üstünde; Kino bir köşeyi düzeltirken karşı sandalyedeki köşe kayıp aşağı düşüyor. Kino şaşkınlıkla kayan uca bakıyor.",satirlar:[{kim:"anlatici",metin:"Bu kez iki ucunu babası, iki ucunu Kino tuttu. Mavi çarşafı dört sandalyenin üstüne birlikte serdiler. Kino çadırın tavanı düz dursun diye sağ köşeyi aşağıya çekti. Şırr! Karşı sandalyedeki köşe kayıp yere düştü. Koşup onu kaldırdı; bu sefer de arkadaki köşe kaydı!"},{kim:"kino",metin:"Baba, bu çarşaf yerinde durmuyor! Bir ucunu tutuyorum, öteki ucu kaçıyor."},{kim:"anlatici",metin:"Kino iki elini sandalyenin sırtına dayayıp bekledi. Bıraksa çarşaf yine kayacaktı."},{kim:"kino",metin:"Dört köşeyi birden nasıl tutacağım?"}]},{no:5,ad:"Küçük Tahta Timsahlar",renk:"#C4DEEE",tarif:"Babası bir mandalı iki parmağıyla sıkıp ağzını açmayı gösteriyor. Kino sandalyenin üst çubuğuna çarşafı mandalla tutturuyor.",satirlar:[{kim:"anlatici",metin:"Babası sepetten tahta bir mandal aldı. İki ucunu başparmağıyla işaret parmağının arasında sıktı. Mandalın ucu küçük bir timsah ağzı gibi açıldı."},{kim:"baba",metin:"Köşeleri senin yerine bunlar tutacak. Önce sıkarak ağzını aç, sonra çarşafla sandalyeyi birlikte kıstır."},{kim:"anlatici",metin:"Kino mandalı iki parmağıyla sıktı. Açılan ucunu çarşafın köşesine geçirdi ve parmaklarını bıraktı. Tık! Mandal kumaşı sandalyenin çubuğuna sımsıkı tutturdu. İkinci köşe… Üçüncü köşe… Dördüncü köşe! Kino çarşafı hafifçe çekti. Hiçbir yerinden kaymadı."},{kim:"kino",metin:"Bak baba! Dördü de tuttu, artık kaçamıyor!"}]},{no:6,ad:"Beşinci Mandalın İşi",renk:"#C4DEEE",tarif:"Mino elinde resimli kitabıyla çadırın önüne gelmiş. Çadırın ön örtüsü aşağı sarktığı için içerisi loş; Lokum halıdaki kırmızı mandalı abisine uzatıyor.",satirlar:[{kim:"anlatici",metin:"Tam o sırada kapı çaldı. Karşı komşuları Mino, kucağında en sevdiği resimli kitapla gelmişti. Üçü birden emekleyerek çadırın içine, Lokum’un sarı minderinin üstüne oturdular. Ama öndeki çarşaf aşağı sarkınca içerisi karanlık kaldı. Kitaptaki resimler seçilmiyordu."},{kim:"mino",metin:"Perdeyi elimle tutsam sayfayı çeviremiyorum."},{kim:"lokum",metin:"Abi, bak! Kırmızı tık-tık kaldı!"},{kim:"anlatici",metin:"Lokum sepette kalan kırmızı mandalı uzattı. Kino çadırın ön örtüsünü yana katladı ve kırmızı mandalla sandalyenin kenarına tutturdu. Tık! Çadırın artık gerçek bir kapısı vardı."}]},{no:7,ad:"Çadırın İçinde Kamp",renk:"#C4DEEE",tarif:"Açık çadır kapısından içerisi görünüyor: Kino sabah hazırladığı sırt çantasından çıkardığı el fenerini tavana tutmuş, Mino kitabı açmış, Lokum sarı minderde elma dilimi yiyor.",satirlar:[{kim:"anlatici",metin:"Kapı açılınca içeriye tatlı bir ışık doldu. Kino sabah parka gitmek için hazırladığı sırt çantasının fermuarını açtı. Önce el fenerini çıkarıp mavi tavana tuttu. Sonra küçük kutusundaki elma dilimlerini Mino ve Lokum’la paylaştı."},{kim:"mino",metin:"Kino, bu çadır hiç bozulmuyor! Üstümüze düşmez, değil mi?"},{kim:"kino",metin:"Düşmez! Köşelerde dört mandal var. Kapıyı da kırmızı mandal tutuyor."},{kim:"anlatici",metin:"Mavi çarşafın altında elma yerken, dışarıdaki yağmurun sesi bile kulağa oyun gibi geliyordu."}]},{no:8,ad:"Beş Mandal Sepete",renk:"#C4DEEE",tarif:"Pencereden güneş açmış. Kino sandalyelerdeki mandalları tek tek sıkıp sepete bırakıyor; babası çarşafı katlamak için bekliyor.",satirlar:[{kim:"anlatici",metin:"Kitabın son sayfasına geldiklerinde pencereden içeriye parlak bir güneş ışığı vurdu. Yağmur dinmişti. Annesi koridordan seslendi:"},{kim:"anne",metin:"Güneş çıktı! Bahçeye inmeden önce çadırı toplamaya kim yardım eder?"},{kim:"kino",metin:"Ben! Mandalları nasıl taktıysam öyle çıkarabilirim."},{kim:"anlatici",metin:"Kino önce kapıdaki kırmızı mandalı sıktı, perdeyi bıraktı. Sonra dört köşedeki tahta mandalları birer birer açıp sepete koydu. Çarşafı da babasıyla karşılıklı ikişer ucundan tutup düzgünce katladılar."}]},{no:9,ad:"Cebimdeki Kırmızı Mandal",renk:"#C4DEEE",tarif:"Apartman kapısından güneşli bahçeye çıkıyorlar. Kino cebinden başı görünen kırmızı mandalı babasına gösteriyor, Mino ve Lokum yanında gülüyor.",satirlar:[{kim:"anlatici",metin:"Ayakkabılarını giyerken Kino sepetteki kırmızı mandalı alıp şortunun cebine koydu. Babası bunu görünce gülümsedi."},{kim:"baba",metin:"Bahçede çarşaf yok ki Kino. O mandalı ne yapacaksın?"},{kim:"kino",metin:"Dursun baba. Belki bahçede de bir şeyin ucu kaçar, kırmızı mandalım tutar!"},{kim:"lokum",metin:"Tık-tık tutar!"},{kim:"anlatici",metin:"Kapıyı açıp güneşli bahçeye çıktılar. Kino elini cebindeki kırmızı mandala değdirdi; bugün kaçan her şeyi nasıl tutacağını öğrenmişti."}]}],ta={baslik:"Birlikte hatırlayalım",sorular:["Kino çarşafı ilk kez tek başına örtmeye çalıştığında ne oldu?","Çarşafın köşeleri kaymasın diye ne kullandılar?","Kırmızı mandal çadırın neresinde işe yaradı?"],not:"Birlikte iki sandalye ve bir örtüyle küçük bir okuma köşesi kurabilirsiniz."},b={id:na,baslik:ea,kapak:ka,sayfalar:ra,ebeveyn:ta},a=(i,n,r,t,e={})=>({id:i,ad:n,yer:r,pozlar:t,...e});fun